def page(q):
 if q['year']==1983 or q['num']<=4:return 5
 return 6 if q['num']<=15 else 7 if q['num']<=28 else 8 if q['num']<=42 else 9
def yes(i,a,e,urls,*,question=None,options=None,num=None,audit='',check=None):
 q=qs[i-41];u=copy.deepcopy(q)
 if num:u['num']=num
 if question:u['question']=question
 if options:u['options']=dict(zip('ABCDE',options))
 u['answer']=a;u['ai_explanation']=e;u['format']=len(u['options'])
 rows.append({'id':q['id'],'before':q,'update':u,'source_pdf_page':page(u),'actual_source_year':u['year'],'actual_source_number':u['num'],'publication_candidate':True,'review_method':'ai-calculation-checked' if check else 'ai-source-checked','independent_reasoning':e,'source_urls':urls,'source_checked_at':'2026-09-12','private_repair_history':audit or 'Complete stem/options visually compared with supplied PDF and independently answered; explanation rewritten as teaching content.','calculation_check':check})
def no(i,why,*,num=None,answer=None):
 q=qs[i-41];tmp={**q,'num':num or q['num']}
 rows.append({'id':q['id'],'before':q,'update':None,'source_pdf_page':page(tmp),'actual_source_year':q['year'],'actual_source_number':tmp['num'],'publication_candidate':False,'hold_reason':why,'independently_indicated_answer':answer,'source_checked_at':'2026-09-12'})

yes(41,'A','The reaction is 1:1 in Zn and H₂SO₄. Acid supplied = 1.0×10/1000 = 0.010 mol, which consumes 0.010×65 = 0.65 g of zinc. The zinc remaining is 2.00 − 0.65 = 1.35 g.',[R],question='Zn + H₂SO₄ → ZnSO₄ + H₂. How much zinc remains undissolved when 2.00 g of zinc reacts with 10 cm³ of 1.0 mol dm⁻³ H₂SO₄? [Zn = 65, S = 32, O = 16, H = 1]',audit='Corrected H₄ to H₂ by atom conservation and wrong D key to A. Old calculation confused zinc consumed with zinc remaining.',check='zinc-remaining')
